function centralRound(len, n, params={}) {
    if (!params.midCircleDiam) params.midCircleDiam = 0.3;
    if (!params.innerDropletSize) params.innerDropletSize = 0.7;
    const phifrac = params.conjoined ? 0.9 : 0.7;

    let phi = TAU / n;

    push();

    strokeWeight(1);
    stroke(fg)
    fill(fg);
    circle(0, 0, len * 2);

    fill(bg);
    stroke(bg);
    circle(0, 0, len * params.midCircleDiam); // tinker
    for (let i = 0; i < n; i++) {
        rotate(phi);

        fill(bg);
        stroke(bg);
        //tinker
        droplet(len * 0.15, len * 0.9, phi, phi * phifrac, 0.7)
        let circ = angularCoords(- phi / 2, 0.85 * len)
        // optional
        if (!params.noMidBalls)
            circle(circ.x, circ.y, len / n);
        fill(fg);
        stroke(fg);
        // tinker
        droplet(len * 0.3, len * 0.7, phi, phi * params.innerDropletSize, 0.7)
    }

    if (params.midCircleDiam >= 0.45) {
        fill(fg);
        stroke(fg);
        circle(0, 0, len * 0.25);
    }
    pop();
}

