function ring(start, stop, thick=true) {
    let frac = thick ? 1 / 3 : 1 / 2;
    let context = createGraphics(2 * stop, 2 * stop);
    noFill();
    // thickness
    let thic = stop - start;
    context.strokeWeight(1);
    context.stroke(fg);
    context.fill(fg);
    context.translate(context.width / 2, context.height / 2);
    context.circle(0, 0, 2 * (start + thic));
    context.erase()
    context.circle(0, 0, 2 * (start + thic * frac));
    context.noErase();


    image(context, 0, 0);
}

function doubleRing(start, stop) {
    let midPoint = start + (stop - start) * 3 / 5;
    ring(start, midPoint);
    ring(midPoint, stop, false);

}


