function circleRing(start, stop) {
    let thic = stop - start;
    let d = thic * 0.7;
    let num = floor((2 * PI * (start + thic * 0.45)) / (d * 1.2) - 3)
    let uangle = TAU / num;
    push();
    strokeWeight(1);
    stroke(fg);
    fill(fg);
    for (let i = 0; i < num; i++) {
        let p = angularCoords(i * uangle, start + thic * 0.45)
        circle(p.x, p.y, d);
    }
    ring(start + thic * 0.8, stop, false);
    pop();
}

