function dropletRing(start, stop) {
    const thic = stop - start;
    const dropletStart = start + thic * 0.1
    const dropletStop = stop - thic * 0.2
    const d = dropletStop - dropletStart;
    const phi = 2 * asin(d / (2 * dropletStop));

    let num = floor((2 * PI * (start + thic * 0.45)) / (d * 1.2) - 3)
    let uangle = TAU / num;
    push();
    strokeWeight(1);
    stroke(fg);
    fill(fg);
    for (let i = 0; i < num; i++) {
        let theta = i * uangle;
        leafFromQuadrilateral([
            angularCoords(theta, dropletStart),
            angularCoords(theta + phi / 2, dropletStart + d * 0.5),
            angularCoords(theta, dropletStop),
            angularCoords(theta - phi / 2, dropletStart + d * 0.5),
        ]);
    }
    ring(start + thic * 0.8, stop, false);
    pop();

}


