function waveRing(start, stop, com=false, dot=false) {
    let thic = stop - start;
    let n = 30;
    let uangle = TAU / n;
    let bpadd = thic * 0.2;
    let ap = [];
    let cp = [];
    let context = createGraphics(2 * stop, 2 * stop);
    context.strokeWeight(1);
    context.stroke(fg);
    context.fill(fg);
    context.translate(context.width / 2, context.height / 2);

    ap.push(angularCoords(0, stop))
    for (let i = 0; i < n; i++) {
        let theta = i * uangle;
        ap.push(angularCoords(theta + uangle / 2, start + bpadd));
        cp.push([angularCoords(theta + uangle / 4, stop), angularCoords(theta + uangle / 4, start + bpadd)]);
        ap.push(angularCoords(theta + uangle, stop));
        cp.push([angularCoords(theta + uangle * 3 / 4, start + bpadd), angularCoords(theta + uangle * 3 / 4, stop)])

        // comma
        if (com) {
            stroke(fg);
            fill(fg);
            commaPattern(i * uangle + uangle / 2, start + thic * 0.7, thic * 0.4, 0);
        }

        if (dot) {
            stroke(fg);
            fill(fg);
            const circ1 = angularCoords(i * uangle, stop + thic * 0.5);
            const circ2 = angularCoords(i * uangle, stop + thic * 1.2);
            circle(circ1.x, circ1.y, 2 * thic * 0.3);
            circle(circ2.x, circ2.y, 2 * thic * 0.15);
        }

    }
    let wave = new BezierCurve(ap, cp);
    wave.draw(context);
    context.erase();
    context.circle(0, 0, start * 2 - 2);
    context.noErase();

    image(context, 0, 0);
}


