// theta is the angle to start with
// phi is the total angle to cover
// startSegment defines the lower cut point of the droplet
function droplet(start, stop, theta, phi, startSegment = 0) {
    let len = stop - start;
    let refPoint = angularCoords(theta, start);
    push()
    translate(refPoint.x, refPoint.y);
    transPoint = angularCoords(theta + PI, (len * startSegment) / 2)
    len += len * startSegment / 2;
    translate(transPoint.x, transPoint.y);

    beginShape();
    angularVertex(theta + phi / 2, len * startSegment)
    angularVertex(theta + phi / 2, len * 0.7)
    quadraticVector(
        // I'm just THAT good in trig
        // I did that shit in my head
        perv({ x: 0, y: 0 }, angularCoords(theta, len), 1, len * tan(phi / 2), -1),
        angularCoords(theta, len)
    );
    quadraticVector(
        perv({ x: 0, y: 0 }, angularCoords(theta, len), 1, len * tan(phi / 2)),
        angularCoords(theta - phi / 2, len * 0.7)
    );
    angularVertex(theta - phi / 2, len * startSegment),
        quadraticVector(
            angularCoords(theta, 0),
            angularCoords(theta + phi / 2, len * startSegment)
        );


    endShape();
    pop()

}

