    let p23 = lerv(points[2], points[3], 0.75);
    let p23_reverse = lerv(points[2], points[1], 0.75);
    let p3 = lerv(points[1], p23, 0.95)
    let p3_reverse = lerv(points[3], p23_reverse, 0.95);
    let p4 = lerv(points[3], points[0], 0.8);
    let p4_reverse = lerv(points[1], points[0], 0.8);
    let p_5 = lerv(p4, points[1], 0.09);
    let p_5_reverse = lerv(p4_reverse, points[3], 0.09);
    let p6 = lerv(points[0], points[2], 0.05);

    beginShape();
    curveVertex(p1.x, p1.y);
    curveVertex(p2.x, p2.y);
    curveVertex(p3.x, p3.y);
    curveVertex(p_5.x, p_5.y);
    vertex(p6.x, p6.y);
    curveVertex(p_5_reverse.x, p_5_reverse.y);
    curveVertex(p3_reverse.x, p3_reverse.y);
    curveVertex(p2.x, p2.y);
    curveVertex(p1_reverse.x, p1_reverse.y);
    endShape();
}

