// d is start len
function fillerOne(theta, d, sf) {
    const patternpath = patternpaths.querySelector('svg#filler-1');
    const patternW = patternpath.getAttribute('width');
    const patternH = patternpath.getAttribute('height');
    // Diagonal distance
    const patternR = Math.hypot(patternH, patternW);
    const SCALE_FACTOR = sf == null ? 0.0097067 * d : sf;
    // this took all my brain cells to figure out
    xyTranslate = (d - (patternR * SCALE_FACTOR) * 0.4) / Math.SQRT2;
    rtheta = (theta - PI / 4) - 0.014;

    [...patternpath.querySelectorAll('path')].forEach(el => {
        const spline = bezierSegmentsFromPath(el);
        fill(fg);
        stroke(fg);
        if (el.id == 'clip') {
            fill(bg);
            stroke(bg);
        }
        push();
        rotate(rtheta);
        translate(xyTranslate, xyTranslate);
        scale(SCALE_FACTOR);
        drawSpline(spline);
        pop()
    });
}

// center, radius, rotation
function commaPattern(theta, d, r, rtheta=0) {
    // radius adjustment
    r = r * 0.66667
    // radial angle
    const c = angularCoords(theta, d)
    push()
    translate(c.x, c.y);
    // default rotation is always away from center
    rotate(-theta + rtheta)

    circle(0, 0, r * 2);
    const ap = [
        { x: 0, y: 0 },
        { x: 0, y: r * 2 },
        { x: r, y: 0 }
    ];
    const cp = [
        [perv(ap[0], ap[1], 0.3, r * 0.7, -1), perv(ap[1], ap[0], 0.3, 0.4 * r, 1)],
        [{ x: 0.4 * r, y: 2 * r }, { x: r, y: 1.5 * r }]
    ];
    let tail = new BezierCurve(ap, cp);
    tail.draw();
    pop()
}


