class BezierCurve {
    // anchorePoints will contain only the anchor points (1D list of vectors)
    // controlPoints is a list of control point pairs
    // to make deactivate a control point, make it null
    // put null instead of control point pairs to make a straight
    // like connection
    constructor(anchorPoints, controlPoints) {
        this.ap = anchorPoints;
        this.cp = controlPoints;
    }

    draw(bf) {
        if (bf == null) {
            beginShape();
            vertex(this.ap[0].x, this.ap[0].y);
            for (let i = 0; i < this.ap.length - 1; i++) {
                let cp1, cp2;
                if (this.cp[i] != null) {
                    cp1 = this.cp[i][0] == null ? this.ap[i] : this.cp[i][0];
                    cp2 = this.cp[i][1] == null ? this.ap[i + 1] : this.cp[i][1];
                } else {
                    cp1 = this.ap[i];
                    cp2 = this.ap[i + 1];
                }
                bezierVertex(cp1.x, cp1.y, cp2.x, cp2.y, this.ap[i + 1].x, this.ap[i + 1].y);
            }
            endShape(CLOSE);
            return;
        }


        bf.beginShape();
        bf.vertex(this.ap[0].x, this.ap[0].y);
        for (let i = 0; i < this.ap.length - 1; i++) {
            let cp1, cp2;
            if (this.cp[i] != null) {
                cp1 = this.cp[i][0] == null ? this.ap[i] : this.cp[i][0];
                cp2 = this.cp[i][1] == null ? this.ap[i + 1] : this.cp[i][1];
            } else {
                cp1 = this.ap[i];
                cp2 = this.ap[i + 1];
            }
            bf.bezierVertex(cp1.x, cp1.y, cp2.x, cp2.y, this.ap[i + 1].x, this.ap[i + 1].y);
        }
        bf.endShape(CLOSE);
    }
}


class CubicBezierSeg {
    constructor(a, b, c, d) {
        this.a = a;
        this.b = b;
        this.c = c;
        this.d = d;
    }

    // finds the point at t, the definition
    P(t) {
        t = Math.max(0, Math.min(1, t)); // very clever way to clamp it to [0,1], thanks dave
        const tc = (1 - t);
        return {
            x: Math.pow(tc, 3) * this.a.x + 3 * Math.pow(tc, 2) * t * this.b.x + 3 * tc * Math.pow(t, 2) * this.c.x + Math.pow(t, 3) * this.d.x,
            y: Math.pow(tc, 3) * this.a.y + 3 * Math.pow(tc, 2) * t * this.b.y + 3 * tc * Math.pow(t, 2) * this.c.y + Math.pow(t, 3) * this.d.y
        }
    }

    // finds the tangent at t
    T(t) {
        t = Math.max(0, Math.min(1, t)); // very clever way to clamp it to [0,1], thanks dave
        const tc = (1 - t) // complement
        // we basically take the derivative of P(t), pretty simple
        return {
            x: 3 * Math.pow(tc, 2) * (this.b.x - this.a.x) + 6 * tc * t * (this.c.x - this.b.x) + 3 * Math.pow(t, 2) * (this.d.x - this.c.x),
            y: 3 * Math.pow(tc, 2) * (this.b.y - this.a.y) + 6 * tc * t * (this.c.y - this.b.y) + 3 * Math.pow(t, 2) * (this.d.y - this.c.y)
        }
    }

    // roughly calculates length by taking samples and calculating their distance
    calculateLength(sampleRate = 2) {
        let totalLength = 0;
        let n = 100; // Start with a large number of segments
        let lastPoint = this.P(0);

        for (let i = 1; i <= n; i++) {
            let t = i / n;
            let currentPoint = this.P(t);

            // Calculate distance between lastPoint and currentPoint
            let dx = currentPoint.x - lastPoint.x;
            let dy = currentPoint.y - lastPoint.y;
            let segmentLength = Math.sqrt(dx * dx + dy * dy);

            totalLength += segmentLength;

            // Update lastPoint for the next segment
            lastPoint = currentPoint;
        }

        // Adjust sample rate by calculating the number of segments again
        const averageSegmentLength = totalLength / n;
        n = Math.round((totalLength / averageSegmentLength) / sampleRate) * sampleRate;

        // Calculate length again with adjusted sample rate
        totalLength = 0;
        lastPoint = this.P(0);

        for (let i = 1; i <= n; i++) {
            let t = i / n;
            let currentPoint = this.P(t);

            // Calculate distance between lastPoint and currentPoint
            let dx = currentPoint.x - lastPoint.x;
            let dy = currentPoint.y - lastPoint.y;
            let segmentLength = Math.sqrt(dx * dx + dy * dy);

            totalLength += segmentLength;

            // Update lastPoint for the next segment
            lastPoint = currentPoint;
        }

        this.totalLength = totalLength;
        return totalLength;
    }
}

class BezierSpline {
    constructor(segs) {
        this.segs = segs;
        this.totalLength = 0;
        this.segs.forEach((s) => {
            this.totalLength += s.calculateLength()
        });
    }
}


// https://stackoverflow.com/questions/64945219/split-a-svg-path-d-to-array-of-objects
const PATH_COMMANDS = {
    M: ["x", "y"],
    m: ["dx", "dy"],
    H: ["x"],
    h: ["dx"],
    V: ["y"],
    v: ["dy"],
    L: ["x", "y"],
    l: ["dx", "dy"],
    Z: [],
    C: ["x1", "y1", "x2", "y2", "x", "y"],
    c: ["dx1", "dy1", "dx2", "dy2", "dx", "dy"],
    S: ["x2", "y2", "x", "y"],
    s: ["dx2", "dy2", "dx", "dy"],
    Q: ["x1", "y1", "x", "y"],
    q: ["dx1", "dy1", "dx", "dy"],
    T: ["x", "y"],
    t: ["dx", "dy"],
    A: ["rx", "ry", "rotation", "large-arc", "sweep", "x", "y"],
    a: ["rx", "ry", "rotation", "large-arc", "sweep", "dx", "dy"]
};

function fromPathToArray(path) {
    const items = path.replace(/[\n\r]/g, '').
        replace(/-/g, ' -').
        replace(/(\d*\.)(\d+)(?=\.)/g, '$1$2 ').
        replace(/(\d)([A-Za-z])/g, '$1 $2').
        replace(/([A-Za-z])(\d)/g, '$1 $2').
        trim().
        split(/\s*,|\s+/)
    const segments = [];
    let currentCommand = '';
    let currentElement = {};
    let _wG_1 = 0; while ((items.length > 0) && ++_wG_1 < 20000) {
        let it = items.shift();
        if (PATH_COMMANDS.hasOwnProperty(it)) {
            currentCommand = it;
        }
        else {
            items.unshift(it);
        }
        currentElement = { type: currentCommand };
        PATH_COMMANDS[currentCommand].forEach((prop) => {
            it = items.shift();  // TODO sanity check
            currentElement[prop] = parseFloat(it);
        });
        if (currentCommand === 'M') {
            currentCommand = 'L';
        }
        else if (currentCommand === 'm') {
            currentCommand = 'l';
        }
        segments.push(currentElement);
    }
    return segments
}

function bezierSegmentsFromPath(el) {
    const commands = fromPathToArray(el.getAttribute('d'))
    const segs = [];
    let connectorPoint = { x: commands[0].x, y: commands[0].y };

    for (let i = 0; i < commands.length; i++) {
        const command = commands[i];
        switch(command.type) {
            case 'C':
                segs.push(new CubicBezierSeg(
                    connectorPoint,
                    { x: command.x1, y: command.y1 },
                    { x: command.x2, y: command.y2 },
                    { x: command.x, y: command.y }
                ));
                connectorPoint = { x: command.x, y: command.y };
                break;
            case 'L':
                segs.push(new CubicBezierSeg(
                    connectorPoint,
                    connectorPoint,
                    { x: command.x, y: command.y },
                    { x: command.x, y: command.y }
                ));
                break;
            case 'V':
                segs.push(new CubicBezierSeg(
                    connectorPoint,
                    connectorPoint,
                    { x: connectorPoint.x, y: command.y },
                    { x: connectorPoint.x, y: command.y }
                ));
                break;
            case 'H':
                segs.push(new CubicBezierSeg(
                    connectorPoint,
                    connectorPoint,
                    { x: command.x, y: connectorPoint.y },
                    { x: command.x, y: connectorPoint.y }
                ));
                break;
            case 'F':
                break;
            default:
                break;
        }
    }
