}

function alpona(pos, r) {
    push()
    let left = 1, stop;
    translate(pos.x, pos.y)
    doCentralPattern(r * 0.25)
    left -= 0.25;
    stop = doRing(r * (1 - left));
    left = 1 - stop / r;
    stop = r * (1 - left) + random(0.0254, 0.04) * w;
    doThinContentRing(r * (1 - left), stop);
    left = 1 - stop / r;
    stop = twirlOneRing(r * (1 - left), random([1, 2, 3]))
    left = 1 - stop / r;
    stop = r * (1 - left) + 0.0254 * w;
    ring(r * (1 - left), stop)
    left = 1 - stop / r;
    stop = r * (1 - left) + random(0.0254, 0.04) * w;
    doThinContentRing(r * (1 - left), stop, noWave = true)
    left = 1 - stop / r;
    stop = r * (1 - left) + random(0.0254, 0.04) * w;
    start = r * (1 - left);
    waveRing(start, start + (stop - start) / 2, random([true, false]), random([false, false, true]));

    outerDecorative(stop)
    pop()
}

function outerDecorative(r) {
    const choice = randi(0, 2);
    stroke(fg);
    fill(fg);
    for (let i = 0; i < 4; i++) {
        if (choice == 0)
            fillerOne(i * HALF_PI + PI / 4, r + r * 0.2, 1.3)
        else if (choice == 1)
            flowerTwo(angularCoords(PI / 4 + i * HALF_PI, r + r * 0.3), r * 0.12, randi(5, 8))
        else if (choice == 2)
            flowerOne(angularCoords(PI / 4 + i * HALF_PI, r + r * 0.3), r * 0.12, randi(5, 8))

    }

}

function doThinContentRing(start, stop, noWave = false) {
    const upperLim = noWave ? 4 : 5;
    const choice = randi(0, upperLim);
    switch (choice) {
        case 0:
            circleRing(start, stop);
            break
        case 1:
            flowerRing(start, stop, randi(5, 8), 1);
            break
        case 2:
            flowerRing(start, stop, randi(5, 8), 2);
            break
        case 3:
            dropletRing(start, stop)
            break
        case 4:
            commaRing(start, stop, random([0, HALF_PI, -HALF_PI, PI]));
            break
        case 5:
            waveRing(start, start + (stop - start) / 2, random([true, false]))
            break
        default:

    }
}

