// Finds the point that is perpendicular to 
// the connecting line and d distance away 
// from the lerped point with fraction f
// s defines which of the possible two points to choose
// +1 or -1
// Useful in Bezier
function perp(x1, y1, x2, y2, f, d, s = 1) {
    const ed = Math.sqrt(Math.pow((x2 - x1), 2) + Math.pow((y2 - y1), 2));
    const dx = d * (-y2 + y1) / ed;
    const dy = d * (x2 - x1) / ed;
    const xa = lerp(x1, x2, f);
    const ya = lerp(y1, y2, f);
    return { x: xa + s * dx, y: ya + s * dy };
}

function perv(v1, v2, f, d, s = 1) {
    return perp(v1.x, v1.y, v2.x, v2.y, f, d, s);
}

function lerv(v1, v2, f) {
    return { x: lerp(v1.x, v2.x, f), y: lerp(v1.y, v2.y, f) };
}

function randi(low, high) {
    return floor(random(low, high + 1));
}

